let timer = null;
let dotNetRef = null;
let timeoutMs = 0;
let isIdle = false;
let container = null;

const events = ["mousemove", "keydown", "click", "scroll"];

function handleActivity() {
    if (timer) clearTimeout(timer);

    if (isIdle) {
        isIdle = false;
        dotNetRef.invokeMethodAsync("OnUserActive");
    }

    timer = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync("OnUserIdle");
    }, timeoutMs);
}

export function initialize(element, ref, timeout) {
    container = element;
    dotNetRef = ref;
    timeoutMs = timeout;
    isIdle = false;

    events.forEach(e => container.addEventListener(e, handleActivity, { passive: true }));

    timer = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync("OnUserIdle");
    }, timeoutMs);
}

export function dispose() {
    if (timer) {
        clearTimeout(timer);
        timer = null;
    }
    if (container) {
        events.forEach(e => container.removeEventListener(e, handleActivity));
        container = null;
    }
    dotNetRef = null;
    isIdle = false;
}

